mapper.select:

where o.is_del = '0'

	AND o.order_no like concat('%', #{orderNo}, '%')


	AND o.waybill_no like concat('%', #{waybillNo}, '%')


	AND o.customer_id = #{customerId}


	AND o.order_status = #{orderStatus}


	AND (
		o.origin_province like concat('%', #{origin}, '%')
		OR o.origin_city like concat('%', #{origin}, '%')
		OR o.origin_district like concat('%', #{origin}, '%')
		OR concat_ws(',', o.origin_province, o.origin_city, o.origin_district) like concat('%', #{origin}, '%')
	)


	AND (
		o.destination_province like concat('%', #{destination}, '%')
		OR o.destination_city like concat('%', #{destination}, '%')
		OR o.destination_district like concat('%', #{destination}, '%')
		OR concat_ws(',', o.destination_province, o.destination_city, o.destination_district) like concat('%', #{destination}, '%')
	)


	AND o.create_time >= #{beginOrderTime}


	AND o.create_time <= #{endOrderTime}

order by o.create_time desc

