waybill_no = #{waybillNo}, customer_id = #{customerId}, order_status = #{orderStatus}, order_source = #{orderSource}, transport_type = #{transportType}, sender_name = #{senderName}, sender_phone = #{senderPhone}, origin_province = #{originProvince}, origin_city = #{originCity}, origin_district = #{originDistrict}, sender_address = #{senderAddress}, receiver_name = #{receiverName}, receiver_phone = #{receiverPhone}, destination_province = #{destinationProvince}, destination_city = #{destinationCity}, destination_district = #{destinationDistrict}, receiver_address = #{receiverAddress}, expect_arrive_time = #{expectArriveTime}, remark = #{remark}, update_by = #{updateBy}, update_time = sysdate()
where order_id = #{orderId}

